select u.id, u.username, u.full_name, u.password, u.status, u.phone, u.sex, u.avatar, u.login_ip, u.login_date, u.create_time, u.update_time, u.remark, GROUP_CONCAT(r.role_name separator ',') AS roleName,GROUP_CONCAT(r.id separator ',') AS roleIdList from sys_user u LEFT JOIN sys_user_role ur ON u.id = ur.user_id LEFT JOIN sys_role r ON ur.role_id = r.id
and u.username != "admin"
and u.full_name like concat('%', #{fullName}, '%')
and u.status = #{status}
and u.phone like concat('%', #{phone}, '%')
and u.sex = #{sex}
and r.role_name like concat('%', #{roleName}, '%')
and u.remark = #{remark}
GROUP BY u.id, u.username, u.full_name, u.password, u.status, u.phone, u.sex, u.avatar, u.login_ip, u.login_date, u.create_time, u.update_time, u.remark order by u.create_time desc limit #{pageable.offset}, #{pageable.pageSize}

select count(1) from sys_user u LEFT JOIN sys_user_role ur ON u.id = ur.user_id LEFT JOIN sys_role r ON ur.role_id = r.id
and u.username != 'admin'
and u.full_name like concat('%', #{fullName}, '%')
and u.status = #{status}
and u.phone like concat('%', #{phone}, '%')
and u.sex = #{sex}
and r.role_name like concat('%', #{roleName}, '%')
and u.remark = #{remark}

